INSERT OR IGNORE INTO projects (slug, title, category, category_label, location, image, url, highlight, challenge, solution, metrics, sort, published) VALUES ('practicekoro', 'PracticeKoro', 'education', 'EXAM PREP PLATFORM', 'West Bengal', '/assets/portfolio/site_practicekoro.jpg', 'https://practicekoro.online', 'WB govt exam prep', 'Government job aspirants in West Bengal needed one organised, Bengali-first place to practise — instead of scattered PDFs and random question banks.', 'A Bengali-first mock test platform for West Bengal government exams — topic tests, full mock tests, previous-year papers and detailed solutions, all in one place.', '[{"value":"5+","label":"Exam categories"},{"value":"PYQ","label":"With detailed solutions"},{"value":"বাংলা","label":"Bengali-first experience"}]', 1, 1);
INSERT OR IGNORE INTO projects (slug, title, category, category_label, location, image, url, highlight, challenge, solution, metrics, sort, published) VALUES ('telepost', 'TelePost', 'education', 'EDTECH · AI SAAS', 'telepost.tech', '/assets/portfolio/site_telepost.jpg', 'https://telepost.tech', 'AI · Telegram', 'Teachers running Telegram channels were spending hours every week writing quiz questions and posting them one by one.', 'An AI quiz generator that turns any topic or PDF into exam-quality quizzes and auto-posts them to Telegram channels — with scheduling and instant explanations.', '[{"value":"20","label":"Quizzes posted in under a minute"},{"value":"PDF→Quiz","label":"AI generation"},{"value":"Auto","label":"Telegram scheduling"}]', 2, 1);
INSERT OR IGNORE INTO projects (slug, title, category, category_label, location, image, url, highlight, challenge, solution, metrics, sort, published) VALUES ('tr-solutions-academy', 'TR Solutions Academy', 'education', 'EDUCATION PLATFORM', '', '/assets/portfolio/site_trsolutions.jpg', '', 'Education platform', 'An academy that needed a modern online home for its courses and students.', 'An education platform for TR Solutions Academy — course information, student enquiries and a clean, mobile-first experience.', '[]', 3, 1);
